	inline json PerformanceSchema()
	{
		auto properties = PerformanceToolPolicy::EnvelopeProperties({ "status", "start_quick_scan", "start_quick_scan_batch",
			"start_feature_cost", "start_feature_costs", "start_upscaling_sweep", "set_feature_enabled", "cancel",
			"results_status", "refresh_results", "load_result", "export_result", "export_session", "retry_results" });
		for (const auto* key : { "recordFpsVR", "enabled", "comparison" }) properties[key] = { { "type", "boolean" } };
		for (const auto* key : { "featureShortName", "dlssPreset", "resultId", "comparisonId" })
			properties[key] = { { "type", "string" }, { "maxLength", 128 } };
		properties["matrix"] = { { "type", "string" }, { "enum", { "auto", "nvidia", "amd" } } };
		properties["format"] = { { "type", "string" }, { "enum", { "csv", "html", "both" } } };
		properties["directory"] = { { "type", "string" }, { "minLength", 1 }, { "maxLength", 4096 } };
		return PerformanceToolPolicy::Schema(std::move(properties));
	}
